// PaymentServiceServer is the server API for PaymentService service.
// All implementations must embed UnimplementedPaymentServiceServer
// for forward compatibility.
//
// Payment Service - 支付服務 gRPC 接口（與 Java payment-service 同步）
type PaymentServiceServer interface {
	// 建立支付交易
	CreatePayment(context.Context, *CreatePaymentRequest) (*CreatePaymentResponse, error)
	// 查詢支付詳情
	GetPayment(context.Context, *GetPaymentRequest) (*GetPaymentResponse, error)
	// §2A.3.6 / §2A.6 查詢同 order_id 的所有付款嘗試（含 CLOSED_BY_SWITCH / 副 row）
	GetPaymentHistory(context.Context, *GetPaymentHistoryRequest) (*GetPaymentHistoryResponse, error)
	// #2501 賣家視角付款歷程：由 Gateway 解出的現任 store_id 驗店家歸屬（一般 GetPaymentHistory 已收斂為 buyer-only）
	GetSellerPaymentHistory(context.Context, *GetSellerPaymentHistoryRequest) (*GetSellerPaymentHistoryResponse, error)
	// 查詢付款狀態（公開，免驗證 — 供付款結果回調頁面使用）
	GetPublicPaymentStatus(context.Context, *GetPublicPaymentStatusRequest) (*GetPublicPaymentStatusResponse, error)
	// 同步查詢支付狀態（呼叫 PayUni Query API）
	SyncPaymentStatus(context.Context, *SyncPaymentStatusRequest) (*SyncPaymentStatusResponse, error)
	// 關閉交易
	ClosePayment(context.Context, *ClosePaymentRequest) (*ClosePaymentResponse, error)
	// 依訂單編號關閉付款交易（Order Service 取消訂單時呼叫，內部 RPC）
	ClosePaymentByOrderNo(context.Context, *ClosePaymentByOrderNoRequest) (*ClosePaymentByOrderNoResponse, error)
	// 依訂單編號反查活躍/最終付款狀態（internal-only，Order Service 逾期取消前守門用）
	// 免權限（isInternalCall()）；以 order_no 為鍵回傳該訂單 canonical 交易的付款狀態
	GetActivePaymentStatusByOrderNo(context.Context, *GetActivePaymentStatusByOrderNoRequest) (*GetActivePaymentStatusByOrderNoResponse, error)
	// 建立退款
	CreateRefund(context.Context, *CreateRefundRequest) (*CreateRefundResponse, error)
	// 查詢退款詳情
	GetRefund(context.Context, *GetRefundRequest) (*GetRefundResponse, error)
	// 查詢交易的所有退款
	GetRefundsByTradeNo(context.Context, *GetRefundsByTradeNoRequest) (*GetRefundsByTradeNoResponse, error)
	// 取得付款結果回調頁面（含 HTML + Deep Link，供 Gateway 透傳）
	GetPaymentReturnPage(context.Context, *GetPaymentReturnPageRequest) (*GetPaymentReturnPageResponse, error)
	// 以 opaque redirect_id 取回付款中轉表單 canonical 欄位（Gateway GET /payment/redirect?id= 用，一次性消費，#1394 反射 XSS 修復）
	GetPaymentRedirectForm(context.Context, *GetPaymentRedirectFormRequest) (*GetPaymentRedirectFormResponse, error)
	// 發動撥款指示（代理商模式：買家確認收貨後，由 Order Service 呼叫）
	GrantPayment(context.Context, *GrantPaymentRequest) (*GrantPaymentResponse, error)
	// ATM 退款頁面版 URL 組裝（AfterSales Service 呼叫）
	GetRefundPageUrl(context.Context, *GetRefundPageUrlRequest) (*GetRefundPageUrlResponse, error)
	// 批次查詢付款 provider 狀態（Order 聚合用，收斂規範 §6.3）
	BatchGetProviderStatusByOrderIds(context.Context, *BatchGetProviderStatusByOrderIdsRequest) (*BatchGetProviderStatusByOrderIdsResponse, error)
	// 批次查詢退款 provider 狀態 by case_ids（AfterSales 聚合用）
	BatchGetRefundProviderStatusByCaseIds(context.Context, *BatchGetRefundProviderStatusByCaseIdsRequest) (*BatchGetRefundProviderStatusResponse, error)
	// 批次查詢退款 provider 狀態 by order_ids（Order 聚合用，取每個 order 最新一筆 payment_refunds）
	BatchGetRefundProviderStatusByOrderIds(context.Context, *BatchGetRefundProviderStatusByOrderIdsRequest) (*BatchGetRefundProviderStatusResponse, error)
	// 信用卡付款 Return 處理（Gateway 接收 PayUni Form POST 後呼叫）
	// 解密 + 驗簽 + 更新交易狀態 + 組裝 Deep Link
	HandlePaymentPageReturn(context.Context, *HandlePaymentPageReturnRequest) (*HandlePaymentPageReturnResponse, error)
	// 送出多功能收付。
	// 🔴 呼叫端必須**先落地 trade_no** 才呼叫本 RPC（70 §3.3 pre-commit）；
	// 🔴 **本 RPC 不負責去重**——PayUni 官方三處逐字標 TradeNo「可重複」，
	//
	//	去重只能由呼叫端的 DB UNIQUE 保證。
	SubmitAgentFee(context.Context, *SubmitAgentFeeRequest) (*SubmitAgentFeeResponse, error)
	// 查詢多功能收付的撥款結果（agent_fee_query）。
	// 回 FundDate 與實際 Fee —— 那是「平台到底收到多少」的唯一來源。
	QueryAgentFee(context.Context, *QueryAgentFeeRequest) (*QueryAgentFeeResponse, error)
	// PayUni 加密資料通用解密（供其他微服務呼叫，如 AfterSales ATM 退款回調）
	DecryptPayUniResult(context.Context, *DecryptPayUniResultRequest) (*DecryptPayUniResultResponse, error)
	// Apple Pay on Web Merchant Validation：對 Apple validationURL 取 merchantSession
	// 使用 Apple Pay Merchant Identity Certificate (PEM + Key) 進行 mTLS POST，原樣透傳 Apple 回應
	// 詳見 05 號設計書 §5.11
	ValidateApplePayMerchant(context.Context, *ValidateApplePayMerchantRequest) (*ValidateApplePayMerchantResponse, error)
	// ATM 退款頁面版受理成功確認（收斂規範 §4.4 雙階段 sync 階段 → PROCESSING + estimated_refund_date）
	// AfterSales 解密 PayUni 回頁面 payload 後呼叫
	AckAtmRefundAccepted(context.Context, *AckAtmRefundAcceptedRequest) (*AckAtmRefundAcceptedResponse, error)
	// 列付款異常（FAILED / EXPIRED / CONFLICT 或 rescue_action 有值）
	ListPaymentTransactionsForAdmin(context.Context, *ListPaymentTransactionsForAdminRequest) (*ListPaymentTransactionsForAdminResponse, error)
	// 取付款詳情（Admin 對帳用，含 grant_* 撥款欄位、rescue、重複付款等）
	GetPaymentTransactionForAdmin(context.Context, *GetPaymentTransactionForAdminRequest) (*GetPaymentTransactionForAdminResponse, error)
	// 列退款異常（FAILED 或處理超時 24h）
	ListRefundsForAdmin(context.Context, *ListRefundsForAdminRequest) (*ListRefundsForAdminResponse, error)
	// 取退款詳情
	GetRefundForAdmin(context.Context, *GetRefundForAdminRequest) (*GetRefundForAdminResponse, error)
	// 列撥款異常（grant_status 非成功）
	ListGrantsForAdmin(context.Context, *ListGrantsForAdminRequest) (*ListGrantsForAdminResponse, error)
	// ==== 服務間：發票日期與金額所需的付款事實（58 號 §7.1.2 步驟 5 ②、註 2）====
	// invoice-service 的 order.paid consumer 專用；唯讀，**不改支付服務任何狀態機**。
	// 走 52 號 HMAC 內部授權四 header，client deadline 3s。
	// 既有的 AdminPaymentTransactionDetail 雖然也帶 provider_paid_at，但那是 admin 面 DTO，
	// 服務間直用違反角色分離（Proto 管理規範 §5.1）。
	GetPaymentFactsInternal(context.Context, *GetPaymentFactsInternalRequest) (*GetPaymentFactsInternalResponse, error)
	mustEmbedUnimplementedPaymentServiceServer()
}

